enum PriorityTier {
  P0_CHECKOUT = 0,     // Never drop
  P1_INTERACTIVE = 1,  // Drop under extreme load
  P2_BACKGROUND = 2,   // Drop when queue depth > 50
  P3_SCRAPERS = 3,     // Drop first when CPU > 75%
}

export function loadSheddingMiddleware(req: Request, res: Response, next: NextFunction) {
  const tier = extractPriorityTier(req);
  const currentCpuUsage = getProcessCpuPercentage();
  const queueDepth = getActiveQueueDepth();

  // Progressively shed lower priority cohorts
  if (currentCpuUsage > 80 && tier >= PriorityTier.P3_SCRAPERS) {
    return res.status(429).setHeader('Retry-After', '30').send('Rate limit exceeded');
  }
  if (queueDepth > 100 && tier >= PriorityTier.P2_BACKGROUND) {
    return res.status(503).setHeader('Retry-After', '10').send('Service temporarily congested');
  }

  next(); // Admit high-priority traffic
}
